    "starterCode": "// Generalization munosabatini yarating\nabstract class Payment {\n    private String paymentId;\n    protected double amount;\n    public Payment(String id, double amount) { this.paymentId = id; this.amount = amount; }\n    public String getPaymentId() { return paymentId; }\n    public abstract double calculateFee();\n}\n\nclass CardPayment extends Payment {\n    public CardPayment(String id, double amount) { super(id, amount); }\n    @Override\n    public double calculateFee() { return amount * 0.01; }\n}\n\nclass Main {\n    public static void main(String[] args) {\n        CardPayment cp = new CardPayment(\"PAY-101\", 100000.0);\n        System.out.println(\"To'lov: \" + cp.getPaymentId() + \" | Komissiya: \" + cp.calculateFee());\n    }\n}",
